; c08_cascade -- CASCADE_BEGIN / CASCADE_END
; Layer-1 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: MainBranchDesc types 1 and 2; cumulative blocks: selector k runs block 0 .. block k
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: c08_cascade.expected.csv
.include "conf_defs.inc"
.main
    CASCADE_BEGIN 1, blk0                      ; selector 1: block 0 and block 1 run, block 2 does not
blk0:
    EXEC_CSR WRITE8 RES + 0, 0xB0
    CASCADE_END 0, out
    EXEC_CSR WRITE8 RES + 1, 0xB1
    CASCADE_END 1, out
    EXEC_CSR WRITE8 RES + 2, 0xB2
    CASCADE_END 2, out
out:
    EXEC_CSR WRITE8 RES + 3, 0xEE
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
